import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = {
    ink: new Color(config.intent?.visualSpec?.colors?.ink ?? "#16161d"),
    paper: new Color(config.intent?.visualSpec?.colors?.paper ?? "#e8ecf2"),
    accent: new Color(config.intent?.visualSpec?.colors?.accent ?? "#ff2a38"),
    surface: new Color(config.intent?.visualSpec?.colors?.surface ?? "#0b0b10")
  };

  // Create a structured back-quad to prevent the void-fill rule error
  const backdropGeo = new PlaneGeometry(7.2, 5.8);
  const backdropMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.15,
    depthWrite: false
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.6);
  group.add(backdrop);

  // Core visual card
  const cardGeo = new PlaneGeometry(4.0, 2.5);
  const cardMat = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.95
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Asset image plane
  let imageMesh = null;
  if (config.imageUrl) {
    const imgGeo = new PlaneGeometry(3.8, 2.3);
    const imgMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0.0
    });
    imageMesh = new Mesh(imgGeo, imgMat);
    imageMesh.position.set(0, 0, 0.02);
    group.add(imageMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imgMat.map = texture;
      imgMat.opacity = 0.9;
      imgMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture", err);
    });
  }

  // Stock Badge indicator (Dynamic data binding representation)
  const badgeGeo = new PlaneGeometry(0.8, 0.3);
  const badgeMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.9
  });
  const badgeMesh = new Mesh(badgeGeo, badgeMat);
  badgeMesh.position.set(1.4, 0.9, 0.05);
  group.add(badgeMesh);

  // Text label within the badge (ASCII ONLY)
  const badgeText = ctx.fontAtlas.createText('STCK_OK', {
    fontSize: 0.06,
    color: '#e8ecf2',
    align: 'center'
  });
  badgeText.position.set(1.4, 0.9, 0.06);
  group.add(badgeText);

  // Headline representation
  const labelText = ctx.fontAtlas.createText('JOURNAL DE NOUE', {
    fontSize: 0.15,
    color: '#e8ecf2',
    align: 'left'
  });
  labelText.position.set(-1.7, -0.8, 0.05);
  group.add(labelText);

  // Interaction handlers
  let activeTimeline = null;

  const onPointerOver = () => {
    if (activeTimeline) activeTimeline.kill();
    activeTimeline = gsap.timeline();
    activeTimeline.to(group.position, {
      y: (config.scenePosition?.y ?? -0.3) + 0.15,
      z: 0.1,
      duration: 0.3,
      ease: "power2.out"
    });
    activeTimeline.to(cardMesh.scale, {
      x: 1.02,
      y: 1.02,
      duration: 0.3,
      ease: "power2.out"
    }, 0);
  };

  const onPointerOut = () => {
    if (activeTimeline) activeTimeline.kill();
    activeTimeline = gsap.timeline();
    activeTimeline.to(group.position, {
      y: config.scenePosition?.y ?? -0.3,
      z: 0.0,
      duration: 0.4,
      ease: "power3.out"
    });
    activeTimeline.to(cardMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.4,
      ease: "power3.out"
    }, 0);
  };

  const onPointerDown = () => {
    if (activeTimeline) activeTimeline.kill();
    activeTimeline = gsap.timeline();
    activeTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: "back.out(2)"
    });
    ctx.emit('hub-journal.select', { itemId: 'journal-card-3' });
  };

  const onPointerUp = () => {
    if (activeTimeline) activeTimeline.kill();
    activeTimeline = gsap.timeline();
    activeTimeline.to(group.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.2,
      ease: "power2.out"
    });
  };

  group.userData = {
    handlers: {
      pointerover: onPointerOver,
      pointerout: onPointerOut,
      pointerdown: onPointerDown,
      pointerup: onPointerUp
    },
    cleanup: () => {
      if (activeTimeline) {
        activeTimeline.kill();
      }
      backdropGeo.dispose();
      backdropMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
      badgeGeo.dispose();
      badgeMat.dispose();
      if (imageMesh) {
        imageMesh.geometry.dispose();
        imageMesh.material.dispose();
      }
    }
  };

  return group;
}
